"""Legacy CRMScript numeric division semantics."""


def _coerce_numeric(value) -> float:
    """Apply legacy numeric coercion for supported operands."""
    if value is None or value == "":
        return 0.0
    return float(value)


def safe_div(a, b) -> tuple[float, list[str]]:
    """Divide using the legacy division-by-zero behavior."""
    divisor = _coerce_numeric(b)
    if divisor == 0.0:
        return 0.0, ["SCRIPT_DIV0"]

    dividend = _coerce_numeric(a)
    return float(dividend / divisor), []
